    /**
     * Tests creating a new Allergy.
     *
     * @return    Allergy
     */
    public Allergy testCreate() throws Throwable {
    Allergy entity = null;

    LOGGER.info( "AllergyTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Allergy");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Allergy" );

    try {
        entity = service.createAllergy( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getAllergyId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Allergy with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

