    /**
     * Tests getting all Allergys.
     *
     * @return    Collection
     */
    public List<Allergy> testGetAll() throws Throwable {
    LOGGER.info( "AllergyTest:testGetAll() - Retrieving Collection of Allergys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Allergy : " );
    List<Allergy> collection  = null;

    try {
        // call the static get method on the AllergyService
        collection = service.getAllAllergy();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Allergy currEntity  = null;
            Iterator<Allergy> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAllergyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

